'use strict';
process.env.LT_REVIVAL_TEST='1';
const {app,BrowserWindow}=require('electron'),fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict');
const policy=require('../../deploy/core/proof-policy.cjs'),projects=require('../../deploy/core/revival-projects.cjs'),preview=require('../../deploy/core/revival-preview.cjs'),npm=require('../../deploy/core/revival-npm.cjs'),memory=require('../../deploy/core/proof-memory.cjs');
const root=path.join(policy.root,'server-watch',crypto.randomUUID());fs.mkdirSync(root,{recursive:true});projects.activate(root);
const helper=path.join(root,'helper.mjs'),manifest=path.join(root,'package.json'),compiler=require.resolve('../../deploy/core/node_modules/esbuild');
const source=factor=>'export function double(n){return n * '+factor+';}globalThis.double=double;globalThis.initial=double(21);';
fs.writeFileSync(helper,source(2));fs.writeFileSync(path.join(root,'index.html'),'<h1>Compiled watches</h1><script type="module" src="/helper.mjs"></script>');
fs.writeFileSync(path.join(root,'server.cjs'),`const http=require('http'),fs=require('fs'),zlib=require('zlib'),compiler=require(${JSON.stringify(compiler)});
function compiled(mode){return compiler.transformSync(fs.readFileSync('helper.mjs','utf8'),{loader:'js',sourcefile:'helper.mjs',sourcemap:mode==='inline'?'inline':'external',banner:'// compiler header'});}
http.createServer((request,response)=>{const url=new URL(request.url,'http://fixture'),pathname=url.pathname,mode=fs.existsSync('map-mode.txt')?fs.readFileSync('map-mode.txt','utf8'):'inline';
 if(pathname==='/'){response.writeHead(200,{'content-type':'text/html'});response.end(fs.readFileSync('index.html'));}
 else if(pathname==='/helper.mjs'){const result=compiled(mode),reference=mode==='outside'?'http://127.0.0.1:1/map':'maps/helper.map?mode='+mode;response.writeHead(200,{'content-type':'application/javascript'});response.end(result.code+(mode==='inline'?'':'\\n//# sourceMappingURL='+reference));}
 else if(pathname==='/maps/helper.map'){const variant=url.searchParams.get('mode');
  if(variant==='missing'){response.writeHead(404);response.end('missing');return;}
  if(variant==='redirect'){response.writeHead(302,{location:'http://127.0.0.1:1/map'});response.end();return;}
  if(variant==='slow'){const timer=setTimeout(()=>response.end('{}'),4000);response.on('close',()=>clearTimeout(timer));return;}
  const map=JSON.parse(compiled('external').map);map.sourceRoot='../';const text=variant==='broken'?'{':variant==='oversized'?' '.repeat(7*1024*1024):JSON.stringify(variant==='indexed'?{version:3,sections:[{offset:{line:0,column:0},map}]}:map);response.writeHead(200,{'content-type':'application/json','content-encoding':'gzip'});response.end(zlib.gzipSync(Buffer.from(text)));
 }else{response.writeHead(404);response.end();}
}).listen(0,'127.0.0.1',function(){console.log('READY http://127.0.0.1:'+this.address().port)});`);
fs.writeFileSync(manifest,JSON.stringify({name:'lt-server-watch',version:'1.0.0',private:true,scripts:{dev:'node server.cjs'}}));
const watchFiles=(text=fs.readFileSync(helper,'utf8'),expression)=>[{path:helper,source:text,watches:[{id:'double',from:text.indexOf('n * '),to:text.indexOf('n * ')+text.match(/n \* \d+/)[0].length,...(expression?{expression}:{})}]}];
const owner=915,checks=[],sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));let host;
async function check(label,fn){await fn();checks.push(label);console.log(label);fs.writeFileSync(path.join(policy.root,'server-watch-progress.json'),JSON.stringify({checks,pid:process.pid}));}
async function until(fn){const deadline=Date.now()+6000;while(!fn()){if(Date.now()>deadline)throw Error('Server condition timed out');await sleep(30);}}
const evaluate=code=>preview.evaluate(owner,code),value=()=>preview.status(owner)?.watches.find(item=>item.id==='double')?.result;
const deadline=setTimeout(()=>app.exit(2),65000);
app.whenReady().then(async()=>{
 let result;try{
  host=new BrowserWindow({show:false,webPreferences:{sandbox:true,nodeIntegration:false,contextIsolation:true,backgroundThrottling:false}});await host.loadURL('data:text/html,<title>Server watch host</title>');
  await npm.start(owner,{kind:'server',path:manifest,source:fs.readFileSync(manifest,'utf8'),script:'dev'});await until(()=>npm.status(owner).output.stdout.includes('READY http://'));
  let initial;
  await check('Compiled HTTP scripts populate real browser watches under both quotas',async()=>{initial=await preview.start(owner,{mode:'server',serverId:npm.status(owner).id,watchFiles:watchFiles(),requestId:crypto.randomUUID()},host);assert.equal(value(),'42');assert.equal(initial.watchSnapshot.bindings[0].status,'bound');assert.equal(initial.memory.hardPrivateCommit,true);assert.equal(npm.status(owner).memory.hardPrivateCommit,true);});
  await check('Server response snapshots remain original while instrumented code executes',async()=>{const served=initial.project.files.find(item=>item.name==='/helper.mjs');assert(served.source.includes('sourceMappingURL'));assert(!served.source.includes('__lt_watch_'));assert.equal((await evaluate('double(22)')).result,'44');assert.equal(value(),'44');});
  await check('Live watch updates preserve the actual page renderer and reject old callbacks',async()=>{await evaluate('globalThis.originalDouble=double;undefined');const pid=preview.status(owner).rendererPid;await preview.updateWatches(owner,watchFiles(source(3)));assert.equal(value(),undefined);assert.equal((await evaluate('originalDouble(25)')).result,'50');assert.equal(value(),undefined);assert.equal(preview.status(owner).rendererPid,pid);});
  await check('A newly served module binds the edited source and supplies current observations',async()=>{fs.writeFileSync(helper,source(3));assert.equal((await evaluate('import("/helper.mjs?t=1").then(()=>initial)')).result,'63');assert.equal(value(),'63');assert.equal(preview.status(owner).watchSnapshot.bindings[0].status,'bound');await evaluate('originalDouble(50)');assert.equal(value(),'63');});
  await check('Custom watch configuration changes cannot accept values from older module closures',async()=>{await preview.updateWatches(owner,watchFiles(source(3),'__SELECTION__ + 1'));await evaluate('double(21)');assert.equal(value(),undefined);await evaluate('import("/helper.mjs?t=2").then(()=>double(21))');assert.equal(value(),'64');});
  await check('Compiled error locations undo instrumentation before tracing original positions',async()=>{const broken=source(3).replace('n * 3','(n * 3) + absentValue');fs.writeFileSync(helper,broken);await preview.updateWatches(owner,watchFiles(broken));await assert.rejects(evaluate('import("/helper.mjs?t=3")'),error=>error.location?.path===helper&&error.location.source===broken&&error.location.column===broken.indexOf('absentValue')+1);});
  await check('Unsaved watches remain stale while the server serves a different source',async()=>{fs.writeFileSync(helper,source(3));await preview.updateWatches(owner,watchFiles(source(4)));await evaluate('import("/helper.mjs?t=4").then(()=>double(21))');assert.equal(value(),undefined);assert.equal(preview.status(owner).watchSnapshot.bindings[0].status,'stale');});
  await check('Watch updates for an old preview identity cannot affect its replacement',async()=>{await assert.rejects(Promise.resolve().then(()=>preview.updateWatches(owner,watchFiles(source(3)),crypto.randomUUID())),/replaced/);assert.equal(preview.status(owner).requestId,initial.requestId);});
  await check('Separate indexed maps bind actual browser observations without replacing the renderer',async()=>{const pid=preview.status(owner).rendererPid;fs.writeFileSync(path.join(root,'map-mode.txt'),'indexed');fs.writeFileSync(helper,source(5));await preview.updateWatches(owner,watchFiles(source(5)));assert.equal((await evaluate('import("/helper.mjs?map=indexed").then(()=>initial)')).result,'105');assert.equal(value(),'105');assert.equal(preview.status(owner).rendererPid,pid);assert.equal(preview.status(owner).project.files.find(item=>item.name==='/helper.mjs?map=indexed').sourceMap.status,'ready');});
  for(const [mode,reason] of [['missing','404'],['broken','JSON'],['outside','origin'],['redirect','302'],['oversized','6 MiB'],['slow','1000 ms']])await check('Unavailable '+mode+' maps preserve the page and cannot publish current watch values',async()=>{const factor=6+checks.length,pid=preview.status(owner).rendererPid;fs.writeFileSync(path.join(root,'map-mode.txt'),mode);fs.writeFileSync(helper,source(factor));await preview.updateWatches(owner,watchFiles(source(factor)));assert.equal((await evaluate('import("/helper.mjs?map='+mode+'").then(()=>initial)')).result,String(factor*21));assert.equal(value(),undefined);const status=preview.status(owner),resource=status.project.files.find(item=>item.name==='/helper.mjs?map='+mode);assert.equal(status.rendererPid,pid);assert.equal(status.status,'running');assert.equal(status.watchSnapshot.bindings[0].status,'unmapped');assert.equal(resource.sourceMap.status,'unavailable');assert(resource.sourceMap.reason.includes(reason),resource.sourceMap.reason);});
  await check('Later valid separate maps recover watches and exact original error positions',async()=>{const broken=source(3).replace('n * 3','(n * 3) + absentValue');fs.writeFileSync(path.join(root,'map-mode.txt'),'external');fs.writeFileSync(helper,broken);await preview.updateWatches(owner,watchFiles(broken));await assert.rejects(evaluate('import("/helper.mjs?map=recovered")'),error=>error.location?.path===helper&&error.location.source===broken&&error.location.column===broken.indexOf('absentValue')+1);assert.equal(preview.status(owner).project.files.find(item=>item.name==='/helper.mjs?map=recovered').sourceMap.status,'ready');});
  await check('Stopping npm closes the linked watched preview and all owned jobs',async()=>{await npm.stop(owner);await until(()=>preview.activeCount()===0);assert.equal(memory.status().jobs,0);assert.equal(npm.activeCount(),0);});
  result={passed:true,checks};
 }catch(error){result={passed:false,checks,error:error.stack};console.error(error);}
 await preview.shutdown();await npm.shutdown();await memory.stop();if(host&&!host.isDestroyed())host.destroy();result.cleanup={previewActive:preview.activeCount(),npmActive:npm.activeCount(),...memory.status()};result.passed=result.passed&&result.cleanup.previewActive===0&&result.cleanup.npmActive===0&&result.cleanup.jobs===0&&result.cleanup.pending===0&&!result.cleanup.helperPid;
 fs.writeFileSync(path.join(policy.root,'server-watch-result.json'),JSON.stringify(result,null,2));clearTimeout(deadline);app.exit(result.passed?0:1);
}).catch(error=>{console.error(error);app.exit(1);});
